import { Fragment, type ReactNode } from 'react';

/**
 * A small, dependency-free, SAFE markdown renderer for note/proposal bodies.
 * It never uses dangerouslySetInnerHTML — text is rendered as React children
 * (auto-escaped). Supports: headings (#, ##, ###), bullet/numbered lists,
 * fenced code blocks (```), blockquotes (>), paragraphs, and inline
 * **bold**, *italic*, `code`, and [links](url).
 */

function renderInline(text: string, keyBase: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  // Order matters: code first (so ** inside code isn't parsed), then link, bold, italic.
  const pattern =
    /(`[^`]+`)|(\[[^\]]+\]\([^)]+\))|(\*\*[^*]+\*\*)|(\*[^*]+\*)/g;
  let last = 0;
  let match: RegExpExecArray | null;
  let i = 0;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > last) {
      nodes.push(<Fragment key={`${keyBase}-t${i}`}>{text.slice(last, match.index)}</Fragment>);
    }
    const token = match[0];
    if (token.startsWith('`')) {
      nodes.push(<code key={`${keyBase}-c${i}`}>{token.slice(1, -1)}</code>);
    } else if (token.startsWith('[')) {
      const m = /\[([^\]]+)\]\(([^)]+)\)/.exec(token);
      if (m) {
        nodes.push(
          <a
            key={`${keyBase}-l${i}`}
            href={m[2]}
            target="_blank"
            rel="noreferrer"
            className="text-copper underline decoration-copper/40 underline-offset-2 hover:decoration-copper"
          >
            {m[1]}
          </a>,
        );
      }
    } else if (token.startsWith('**')) {
      nodes.push(<strong key={`${keyBase}-b${i}`}>{token.slice(2, -2)}</strong>);
    } else {
      nodes.push(<em key={`${keyBase}-i${i}`}>{token.slice(1, -1)}</em>);
    }
    last = match.index + token.length;
    i += 1;
  }
  if (last < text.length) {
    nodes.push(<Fragment key={`${keyBase}-end`}>{text.slice(last)}</Fragment>);
  }
  return nodes;
}

export function Markdown({ children, className = '' }: { children: string; className?: string }) {
  const lines = children.replace(/\r\n/g, '\n').split('\n');
  const blocks: ReactNode[] = [];
  let i = 0;
  let b = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block
    if (line.trim().startsWith('```')) {
      const buf: string[] = [];
      i += 1;
      while (i < lines.length && !lines[i].trim().startsWith('```')) {
        buf.push(lines[i]);
        i += 1;
      }
      i += 1; // closing fence
      blocks.push(
        <pre
          key={`b${b++}`}
          className="my-3 overflow-x-auto rounded-lg border border-line bg-paper-deep p-3 font-mono text-[0.8125rem] leading-relaxed text-ink"
        >
          <code>{buf.join('\n')}</code>
        </pre>,
      );
      continue;
    }

    // Blank line
    if (line.trim() === '') {
      i += 1;
      continue;
    }

    // Headings
    const heading = /^(#{1,3})\s+(.*)$/.exec(line);
    if (heading) {
      const level = heading[1].length;
      const cls =
        level === 1
          ? 'font-display text-lg text-ink mt-4 mb-1.5'
          : level === 2
            ? 'font-display text-base text-ink mt-3 mb-1'
            : 'eyebrow text-ink-soft mt-3 mb-1';
      blocks.push(
        <p key={`b${b++}`} className={cls}>
          {renderInline(heading[2], `b${b}`)}
        </p>,
      );
      i += 1;
      continue;
    }

    // Blockquote
    if (line.trimStart().startsWith('> ')) {
      const buf: string[] = [];
      while (i < lines.length && lines[i].trimStart().startsWith('> ')) {
        buf.push(lines[i].trimStart().slice(2));
        i += 1;
      }
      blocks.push(
        <blockquote
          key={`b${b++}`}
          className="my-3 border-l-2 border-copper/40 pl-3 italic text-ink-soft"
        >
          {renderInline(buf.join(' '), `b${b}`)}
        </blockquote>,
      );
      continue;
    }

    // Lists (bullet or numbered)
    const bullet = /^\s*[-*]\s+/;
    const numbered = /^\s*\d+\.\s+/;
    if (bullet.test(line) || numbered.test(line)) {
      const ordered = numbered.test(line);
      const re = ordered ? numbered : bullet;
      const items: string[] = [];
      while (i < lines.length && re.test(lines[i])) {
        items.push(lines[i].replace(re, ''));
        i += 1;
      }
      const inner = items.map((it, idx) => (
        <li key={idx} className="pl-1">
          {renderInline(it, `b${b}-li${idx}`)}
        </li>
      ));
      blocks.push(
        ordered ? (
          <ol key={`b${b++}`} className="my-2 ml-5 list-decimal space-y-1 marker:text-ink-faint">
            {inner}
          </ol>
        ) : (
          <ul key={`b${b++}`} className="my-2 ml-5 list-disc space-y-1 marker:text-copper">
            {inner}
          </ul>
        ),
      );
      continue;
    }

    // Paragraph (gather consecutive non-blank, non-special lines)
    const para: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !lines[i].trim().startsWith('```') &&
      !/^(#{1,3})\s+/.test(lines[i]) &&
      !lines[i].trimStart().startsWith('> ') &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i])
    ) {
      para.push(lines[i]);
      i += 1;
    }
    blocks.push(
      <p key={`b${b++}`}>{renderInline(para.join(' '), `b${b}`)}</p>,
    );
  }

  return <div className={`prose-warm conversation-copy ${className}`}>{blocks}</div>;
}

