import type { Item, ProposalItem as ProposalItemType, ProposalVerdict } from '../../types/conversation';
import { CommentField, ItemShell } from '../conversation/ItemShell';
import { Markdown } from '../ui/Markdown';

interface Props {
  item: ProposalItemType;
  index: number;
  onChange: (patch: Partial<Item>) => void;
}

const VERDICTS: { value: ProposalVerdict; label: string; glyph: string; active: string }[] = [
  { value: 'accepted', label: 'Accepter', glyph: '✓', active: 'border-status-done bg-status-done-bg text-status-done' },
  { value: 'revise', label: 'À réviser', glyph: '↻', active: 'border-status-progress bg-status-progress-bg text-status-progress' },
  { value: 'rejected', label: 'Rejeter', glyph: '✕', active: 'border-copper bg-copper/10 text-copper-deep' },
];

export function ProposalItem({ item, index, onChange }: Props) {
  const current = item.response?.verdict;
  const isCode = Boolean(item.language);

  function commit(next: ProposalVerdict) {
    onChange({
      response: { verdict: next },
      status: 'answered',
      answeredAt: item.answeredAt ?? new Date().toISOString(),
    });
  }

  return (
    <ItemShell
      item={item}
      index={index}
      comment={<CommentField value={item.comment ?? ''} label="Retour / demande de révision" onChange={(v) => onChange({ comment: v || undefined })} />}
    >
      {/* The proposed content, set off as a quoted "manuscript" block */}
      <div className="relative overflow-hidden rounded-lg border border-line bg-paper-raised">
        <div className="flex items-center gap-2 border-b border-line-soft bg-paper-deep/50 px-4 py-2">
          <span className="eyebrow text-copper-deep">Proposition de Claude</span>
          {item.language && (
            <span className="ml-auto font-mono text-[0.6875rem] text-ink-faint">{item.language}</span>
          )}
        </div>
        <div className="px-4 py-3.5">
          {isCode ? (
            <pre className="overflow-x-auto font-mono text-[0.8125rem] leading-relaxed text-ink">
              <code>{item.proposal}</code>
            </pre>
          ) : (
            <Markdown>{item.proposal}</Markdown>
          )}
        </div>
      </div>

      <div className="mt-4 flex flex-wrap gap-2.5">
        {VERDICTS.map((v) => {
          const isActive = current === v.value;
          return (
            <button
              key={v.value}
              type="button"
              aria-pressed={isActive}
              onClick={() => commit(v.value)}
              className={`inline-flex items-center gap-2 rounded-lg border px-4 py-2 text-sm font-medium transition-colors ${
                isActive ? v.active : 'border-line bg-paper-raised text-ink hover:border-copper/45'
              }`}
            >
              <span aria-hidden>{v.glyph}</span>
              {v.label}
            </button>
          );
        })}
      </div>
    </ItemShell>
  );
}

