 * it shows an acknowledge toggle; otherwise it is purely informational and
 * never blocks completion.
 */
export function NoteItem({ item, index, onChange }: Props) {
  const acknowledged = item.response?.acknowledged ?? false;
  const requiresAck = item.requiresAck ?? false;

  function toggleAck() {
    const next = !acknowledged;
    onChange({
      response: next ? { acknowledged: true } : undefined,
      status: next ? 'answered' : 'pending',
